#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<int> lo(n), hi(n);
    int limit = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &lo[i], &hi[i]);
        limit = max(limit, hi[i]);
    }
    vector<char> sieve(limit + 1, 1);
    sieve[0] = 0;
    if (limit >= 1) sieve[1] = 0;
    for (long long p = 2; p * p <= limit; p++)
        if (sieve[p])
            for (long long m = p * p; m <= limit; m += p) sieve[m] = 0;
    // prefix[v] = sum of primes <= v
    vector<long long> prefix(limit + 1, 0);
    for (int v = 1; v <= limit; v++) prefix[v] = prefix[v - 1] + (sieve[v] ? v : 0);
    const long long MOD = 1000000007;
    long long result = 1;
    // Product of per-position prime sums equals the sum over all arrays of their products.
    for (int i = 0; i < n; i++) result = result * ((prefix[hi[i]] - prefix[lo[i] - 1]) % MOD) % MOD;
    printf("%lld\n", result);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] lo = new int[n], hi = new int[n];
        int limit = 0;
        for (int i = 0; i < n; i++) {
            lo[i] = nextInt();
            hi[i] = nextInt();
            limit = Math.max(limit, hi[i]);
        }
        boolean[] composite = new boolean[limit + 1];
        composite[0] = true;
        if (limit >= 1) composite[1] = true;
        for (long p = 2; p * p <= limit; p++)
            if (!composite[(int) p])
                for (long m = p * p; m <= limit; m += p) composite[(int) m] = true;
        // prefix[v] = sum of primes <= v
        long[] prefix = new long[limit + 1];
        for (int v = 1; v <= limit; v++) prefix[v] = prefix[v - 1] + (composite[v] ? 0 : v);
        final long MOD = 1000000007L;
        long result = 1;
        // Product of per-position prime sums equals the sum over all arrays of their products.
        for (int i = 0; i < n; i++) result = result * ((prefix[hi[i]] - prefix[lo[i] - 1]) % MOD) % MOD;
        System.out.println(result);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n := readInt()
	lo := make([]int, n)
	hi := make([]int, n)
	limit := 0
	for i := 0; i < n; i++ {
		lo[i], hi[i] = readInt(), readInt()
		limit = max(limit, hi[i])
	}
	composite := make([]bool, limit+1)
	composite[0] = true
	if limit >= 1 {
		composite[1] = true
	}
	for p := 2; p*p <= limit; p++ {
		if !composite[p] {
			for m := p * p; m <= limit; m += p {
				composite[m] = true
			}
		}
	}
	// prefix[v] = sum of primes <= v
	prefix := make([]int, limit+1)
	for v := 1; v <= limit; v++ {
		prefix[v] = prefix[v-1]
		if !composite[v] {
			prefix[v] += v
		}
	}
	const MOD = 1000000007
	result := 1
	// Product of per-position prime sums equals the sum over all arrays of their products.
	for i := 0; i < n; i++ {
		result = result * ((prefix[hi[i]] - prefix[lo[i]-1]) % MOD) % MOD
	}
	fmt.Println(result)
}
